#pragma once

#include <Eigen/Dense>
#include <vector>
#include <string>
#include <fstream>
#include <sstream>
#include <iostream>
#include <algorithm>
#include <cmath>
#include <chrono>

using Vec3 = Eigen::Vector3d;

struct RigidMesh {
    std::vector<Vec3> vertices;
    std::vector<std::array<int, 3>> faces;
    std::vector<Vec3> face_normals;

    // SDF data (generated by compute_sdf)
    std::vector<float> sdf_data;
    int sdf_res[3] = {0, 0, 0};
    Vec3 sdf_origin;
    Vec3 sdf_cell_size;

    int num_vertices() const { return (int)vertices.size(); }
    int num_faces() const { return (int)faces.size(); }

    bool load_obj(const std::string& path) {
        std::ifstream file(path);
        if (!file.is_open()) {
            std::cerr << "无法打开OBJ: " << path << std::endl;
            return false;
        }

        vertices.clear();
        faces.clear();
        std::string line;
        while (std::getline(file, line)) {
            std::istringstream iss(line);
            std::string token;
            iss >> token;

            if (token == "v") {
                double x, y, z;
                iss >> x >> y >> z;
                vertices.push_back(Vec3(x, y, z));
            } else if (token == "f") {
                std::vector<int> idx;
                std::string part;
                while (iss >> part) {
                    int vi = std::stoi(part.substr(0, part.find('/'))) - 1;
                    idx.push_back(vi);
                }
                for (int i = 1; i + 1 < (int)idx.size(); i++) {
                    faces.push_back({idx[0], idx[i], idx[i + 1]});
                }
            }
        }
        _compute_normals();
        std::cout << "Rigid mesh: " << num_vertices() << " 顶点, "
                  << num_faces() << " 面" << std::endl;
        return true;
    }

    void translate(const Vec3& offset) {
        for (auto& v : vertices) v += offset;
    }

    void get_bounds(Vec3& bmin, Vec3& bmax) const {
        bmin = Vec3(1e10, 1e10, 1e10);
        bmax = Vec3(-1e10, -1e10, -1e10);
        for (auto& v : vertices) {
            bmin = bmin.cwiseMin(v);
            bmax = bmax.cwiseMax(v);
        }
    }

    // Generate SDF: signed distance field on a uniform grid
    // resolution: grid cells per axis (e.g. 128)
    // padding: extra space around bounding box (fraction, e.g. 0.1 = 10%)
    // extra_margin [m]: after the cells are sized from the padded box, add whole cells on every side
    // until the box extends at least extra_margin beyond the padded box. The cell size (resolution)
    // is unchanged; only the grid grows. Used so that queries a given distance away from a thin tool
    // (e.g. the far endpoint of a tissue edge crossing it) still get a valid phi and normal.
    void compute_sdf(int resolution = 128, double padding = 0.1, double extra_margin = 0.0) {
        auto t0 = std::chrono::high_resolution_clock::now();

        Vec3 bmin, bmax;
        get_bounds(bmin, bmax);
        Vec3 extent = bmax - bmin;
        Vec3 pad = extent * padding;
        bmin -= pad;
        bmax += pad;
        extent = bmax - bmin;

        // Resolution per axis (proportional to extent)
        double max_ext = extent.maxCoeff();
        sdf_res[0] = std::max(16, (int)(resolution * extent.x() / max_ext));
        sdf_res[1] = std::max(16, (int)(resolution * extent.y() / max_ext));
        sdf_res[2] = std::max(16, (int)(resolution * extent.z() / max_ext));
        sdf_origin = bmin;
        sdf_cell_size = Vec3(extent.x() / sdf_res[0],
                              extent.y() / sdf_res[1],
                              extent.z() / sdf_res[2]);
        if (extra_margin > 0.0) {
            for (int k = 0; k < 3; k++) {
                int n = (int)std::ceil(extra_margin / sdf_cell_size[k]);
                sdf_res[k] += 2 * n;
                sdf_origin[k] -= n * sdf_cell_size[k];
            }
        }

        int total = sdf_res[0] * sdf_res[1] * sdf_res[2];
        sdf_data.resize(total);

        std::cout << "Computing SDF: " << sdf_res[0] << "x" << sdf_res[1] << "x" << sdf_res[2]
                  << " (" << total << " voxels, " << num_faces() << " faces)..." << std::flush;

        // Step 1: unsigned distance + nearest face index for each voxel
        std::vector<int> nearest_face(total, -1);

        #pragma omp parallel for schedule(dynamic, 64)
        for (int idx = 0; idx < total; idx++) {
            int iz = idx / (sdf_res[0] * sdf_res[1]);
            int iy = (idx / sdf_res[0]) % sdf_res[1];
            int ix = idx % sdf_res[0];

            Vec3 p = sdf_origin + Vec3((ix + 0.5) * sdf_cell_size.x(),
                                        (iy + 0.5) * sdf_cell_size.y(),
                                        (iz + 0.5) * sdf_cell_size.z());

            double min_dist2 = 1e20;
            int best_face = -1;
            for (int fi = 0; fi < num_faces(); fi++) {
                Vec3 cp = _closest_point_on_triangle(p, fi);
                double d2 = (p - cp).squaredNorm();
                if (d2 < min_dist2) {
                    min_dist2 = d2;
                    best_face = fi;
                }
            }
            sdf_data[idx] = (float)std::sqrt(min_dist2);
            nearest_face[idx] = best_face;
        }

        // Step 2: sign via ray casting (+X direction)
        #pragma omp parallel for schedule(dynamic, 64)
        for (int idx = 0; idx < total; idx++) {
            int iz = idx / (sdf_res[0] * sdf_res[1]);
            int iy = (idx / sdf_res[0]) % sdf_res[1];
            int ix = idx % sdf_res[0];

            Vec3 p = sdf_origin + Vec3((ix + 0.5) * sdf_cell_size.x(),
                                        (iy + 0.5) * sdf_cell_size.y(),
                                        (iz + 0.5) * sdf_cell_size.z());
            Vec3 dir(1, 0, 0);  // ray in +X

            int intersections = 0;
            for (int fi = 0; fi < num_faces(); fi++) {
                if (_ray_triangle_intersect(p, dir, fi))
                    intersections++;
            }

            if (intersections % 2 == 1) {
                // inside → negative SDF
                sdf_data[idx] = -sdf_data[idx];
            }
        }

        auto t1 = std::chrono::high_resolution_clock::now();
        double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();

        // Stats
        int inside = 0;
        for (int i = 0; i < total; i++) if (sdf_data[i] < 0) inside++;
        std::cout << " done (" << ms << "ms, " << inside << " inside voxels)" << std::endl;
    }

private:
    void _compute_normals() {
        face_normals.resize(faces.size());
        for (int i = 0; i < (int)faces.size(); i++) {
            Vec3 a = vertices[faces[i][0]];
            Vec3 b = vertices[faces[i][1]];
            Vec3 c = vertices[faces[i][2]];
            Vec3 n = (b - a).cross(c - a);
            double len = n.norm();
            face_normals[i] = (len > 1e-12) ? (n / len) : Vec3(0, 1, 0);
        }
    }

    // Closest point on triangle (Ericson's method)
    Vec3 _closest_point_on_triangle(const Vec3& p, int fi) const {
        Vec3 a = vertices[faces[fi][0]];
        Vec3 b = vertices[faces[fi][1]];
        Vec3 c = vertices[faces[fi][2]];

        Vec3 ab = b - a, ac = c - a, ap = p - a;
        double d1 = ab.dot(ap), d2 = ac.dot(ap);
        if (d1 <= 0 && d2 <= 0) return a;

        Vec3 bp = p - b;
        double d3 = ab.dot(bp), d4 = ac.dot(bp);
        if (d3 >= 0 && d4 <= d3) return b;

        Vec3 cp = p - c;
        double d5 = ab.dot(cp), d6 = ac.dot(cp);
        if (d6 >= 0 && d5 <= d6) return c;

        double vc = d1*d4 - d3*d2;
        if (vc <= 0 && d1 >= 0 && d3 <= 0) {
            double v = d1 / (d1 - d3);
            return a + v * ab;
        }

        double vb = d5*d2 - d1*d6;
        if (vb <= 0 && d2 >= 0 && d6 <= 0) {
            double w = d2 / (d2 - d6);
            return a + w * ac;
        }

        double va = d3*d6 - d5*d4;
        if (va <= 0 && (d4 - d3) >= 0 && (d5 - d6) >= 0) {
            double w = (d4 - d3) / ((d4 - d3) + (d5 - d6));
            return b + w * (c - b);
        }

        double denom = 1.0 / (va + vb + vc);
        double v = vb * denom;
        double w = vc * denom;
        return a + ab * v + ac * w;
    }

    // Möller–Trumbore ray-triangle intersection
    bool _ray_triangle_intersect(const Vec3& origin, const Vec3& dir, int fi) const {
        const double EPS = 1e-12;
        Vec3 a = vertices[faces[fi][0]];
        Vec3 b = vertices[faces[fi][1]];
        Vec3 c = vertices[faces[fi][2]];

        Vec3 e1 = b - a, e2 = c - a;
        Vec3 h = dir.cross(e2);
        double det = e1.dot(h);

        if (std::abs(det) < EPS) return false;  // parallel

        double inv_det = 1.0 / det;
        Vec3 s = origin - a;
        double u = inv_det * s.dot(h);
        if (u < 0.0 || u > 1.0) return false;

        Vec3 q = s.cross(e1);
        double v = inv_det * dir.dot(q);
        if (v < 0.0 || u + v > 1.0) return false;

        double t = inv_det * e2.dot(q);
        return t > EPS;  // intersection at t > 0 (forward along ray)
    }
};
